/*
 * A287300  Primes that can be generated by the concatenation in base 3, in
 *          ascending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287300
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the n-th prime obtained by concatenating the base‑3
 *            representations of two consecutive integers m and m+1. The code
 *            searches m sequentially and returns the nth such prime
 * Range:     u8 n <= 5, u16 n <= 44, u32 n <= 44, u64 n <= 44, u128 n <= 44,
 *            big any n
 * Helpers:   digits_base3, is_prime_big, pow_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include "../utils/pow_seq.h"
#include "../utils/is_prime_big.h"
#include "../utils/digits_base3.h"

seq_t a(idx_t n)
{
    idx_t found = 0;
    idx_t m = 1;
    while (1) {
        int len = digits_base3(m + 1);
        seq_t power = pow_seq((seq_t)3, len);
        seq_t val = (seq_t)m * power + (seq_t)(m + 1);
        if (is_prime_big(val)) {
            found++;
            if (found == n) return val;
        }
        m++;
    }
}
